goF(){return"Mira Antes de Mover"},
goG(){return"Nunca regales un salto"},
goH(){return"Dos por Uno"},
goI(){return"Da una pieza, recupera m\xe1s"},
goC(){return"Avance Decisivo"},
goD(){return"Sacrifica para coronar"},
goA(){return"Encerrarlas"},
goB(){return"Gana dejando al rival sin jugadas"},
